+}
+
+/// The post verbs keep the same law: a post picked on Setup2 is its own,
+/// Setup1 keeps the document's post, and undo gives it back.
+#[test]
+fn a_post_picked_on_setup2_leaves_setup1s_post() {
+    let mut state = State::new();
